170	
171	        c.set('authUser', {
172	          id: e2eBypassUser.id,
173	          email: e2eBypassUser.email,
174	          role: e2eBypassUser.role,
175	          name: e2eBypassUser.name,
176	        });
177	        await next();
178	        return;
179	      }
180	
181	      // 1. Try cookie-based auth (web clients)
182	      let user: SessionLookupUser | null = null;
183	      let impersonatedBy: string | null = null;
184	      try {
185	        const cookieSession = await auth.api.getSession({
186	          headers: requestHeaders,
187	        });
188	        user = cookieSession?.user ?? null;
189	
190	        // Native impersonation (Better Auth admin plugin): when set, the
191	        // session belongs to the impersonated user and `impersonatedBy` is the
192	        // admin's id. Exposed on context for audit/debug and used below to
193	        // reject the super-admin managed-school override during impersonation.
194	        impersonatedBy =
195	          (
196	            cookieSession?.session as
197	              | { impersonatedBy?: string | null }
198	              | undefined
199	          )?.impersonatedBy ?? null;
200	      } catch {
201	        user = null;
202	      }
203	
204	      // 2. Fallback: direct session-token DB lookup for web requests when
205	      // Better Auth's helper cannot resolve the session.
206	      if (!user) {
207	        const cookieToken = getSessionTokenFromCookies(requestHeaders);
208	        if (cookieToken) {
209	          const sessionLookup = await findSessionByToken(cookieToken);
210	          if (sessionLookup) {
211	            user = sessionLookup.user;
212	            impersonatedBy = sessionLookup.impersonatedBy;
213	          }
214	        }
215	      }
216	
217	      // 3. Fallback: Bearer token → direct DB lookup (mobile clients)
218	      if (!user) {
219	        const authHeader = c.req.header('authorization');
220	        if (authHeader?.startsWith('Bearer ')) {
221	          const sessionLookup = await findSessionByToken(authHeader.slice(7));
222	          if (sessionLookup) {
223	            user = sessionLookup.user;
224	            impersonatedBy = sessionLookup.impersonatedBy;
225	          }
226	        }
227	      }
228	
229	      if (!user) {
230	        return c.json({ error: 'Unauthorized: no valid session' }, 401);
231	      }
232	      if (impersonatedBy) c.set('impersonatedBy', impersonatedBy);
233	
234	      // 4. Ensure role is always fetched from database for accuracy.
235	      // Better Auth's getSession() may not include additionalFields (like role)
236	      // in the session response, OR may return the stale default 'user' role
237	      // when the user's role was promoted after session creation.
238	      // Re-verify from the auth_user table when role is missing or default.
239	      let role = user.role as string | null;
240	      if (!role || role === 'user') {
241	        const [dbUser] = await db
242	          .select({ role: authUser.role })
243	          .from(authUser)
244	          .where(eq(authUser.id, user.id))
245	          .limit(1);
246	        role = dbUser?.role ?? 'user';
247	      }
248	      role = role ?? 'user';
249	
250	      if (options?.roles && options.roles.length > 0) {
251	        if (!options.roles.includes(role)) {
252	          return c.json(
253	            {
254	              error: `Forbidden: requires one of [${options.roles.join(', ')}]`,
255	            },
256	            403,
257	          );
258	        }
259	      }
260	
261	      const authUser_: AuthUser = {
262	        id: user.id,
263	        email: user.email,
264	        role,
265	        name: user.name ?? undefined,
266	      };
267	
268	      c.set('authUser', authUser_);
269	
270	      // Super-admin managing a school: store the managed school ID on context
271	      // so resolveOrgIdFromSession can use it instead of the platform school.
272	      //
273	      // Precedence (design D-A): an active impersonation session always wins —
274	      // the impersonated user's own org is authoritative, so the client-supplied
275	      // X-Managed-School-Id header is ignored while impersonating. (In practice
276	      // admins can't be impersonated, so an impersonation session is never
277	      // super_admin; this is defense-in-depth.)
278	      if (authUser_.role === 'super_admin' && !impersonatedBy) {
279	        const managedSchoolId = c.req.header('x-managed-school-id');
280	        if (
281	          managedSchoolId &&
282	          /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
283	            managedSchoolId,
284	          )
285	        ) {
286	          c.set('managedSchoolId', managedSchoolId);
287	        }
288	      }
289	
290	      await next();
291	    } catch (err: unknown) {
292	      const message = extractError(err);
293	      return c.json({ error: `Authentication failed: ${message}` }, 500);
294	    }
295	  };
296	}
